CustomField.formula:
IF(
  ISBLANK(Seg2_Latest_Arrival_Date__c) || ISBLANK(Seg2_Latest_Arrival_Time__c) || ISBLANK(Seg2_Original_Arrival_Date__c) || ISBLANK(Seg2_Original_Arrival_Time__c),
  "",
  IF(
    ROUND(
      (
        DATETIMEVALUE(SUBSTITUTE(Seg2_Latest_Arrival_Date__c, "/", "-") & " " & LEFT(Seg2_Latest_Arrival_Time__c, 5) & ":00")
        -
        DATETIMEVALUE(SUBSTITUTE(Seg2_Original_Arrival_Date__c, "/", "-") & " " & LEFT(Seg2_Original_Arrival_Time__c, 5) & ":00")
      ) * 24 * 60, 0
    ) = 0,
    "(準時)",
    IF(
      ROUND(
        (
          DATETIMEVALUE(SUBSTITUTE(Seg2_Latest_Arrival_Date__c, "/", "-") & " " & LEFT(Seg2_Latest_Arrival_Time__c, 5) & ":00")
          -
          DATETIMEVALUE(SUBSTITUTE(Seg2_Original_Arrival_Date__c, "/", "-") & " " & LEFT(Seg2_Original_Arrival_Time__c, 5) & ":00")
        ) * 24 * 60, 0
      ) > 0,
      "共 (延遲)",
      "共 (提早)"
    ) &
    IF(
      FLOOR(ABS(
        ROUND(
          (
            DATETIMEVALUE(SUBSTITUTE(Seg2_Latest_Arrival_Date__c, "/", "-") & " " & LEFT(Seg2_Latest_Arrival_Time__c, 5) & ":00")
            -
            DATETIMEVALUE(SUBSTITUTE(Seg2_Original_Arrival_Date__c, "/", "-") & " " & LEFT(Seg2_Original_Arrival_Time__c, 5) & ":00")
          ) * 24 * 60, 0
        )
      ) / 60) > 0,
      TEXT(FLOOR(ABS(
        ROUND(
          (
            DATETIMEVALUE(SUBSTITUTE(Seg2_Latest_Arrival_Date__c, "/", "-") & " " & LEFT(Seg2_Latest_Arrival_Time__c, 5) & ":00")
            -
            DATETIMEVALUE(SUBSTITUTE(Seg2_Original_Arrival_Date__c, "/", "-") & " " & LEFT(Seg2_Original_Arrival_Time__c, 5) & ":00")
          ) * 24 * 60, 0
        )
      ) / 60)) & "小時", ""
    ) &
    IF(
      MOD(ABS(
        ROUND(
          (
            DATETIMEVALUE(SUBSTITUTE(Seg2_Latest_Arrival_Date__c, "/", "-") & " " & LEFT(Seg2_Latest_Arrival_Time__c, 5) & ":00")
            -
            DATETIMEVALUE(SUBSTITUTE(Seg2_Original_Arrival_Date__c, "/", "-") & " " & LEFT(Seg2_Original_Arrival_Time__c, 5) & ":00")
          ) * 24 * 60, 0
        )
      ), 60) > 0,
      TEXT(MOD(ABS(
        ROUND(
          (
            DATETIMEVALUE(SUBSTITUTE(Seg2_Latest_Arrival_Date__c, "/", "-") & " " & LEFT(Seg2_Latest_Arrival_Time__c, 5) & ":00")
            -
            DATETIMEVALUE(SUBSTITUTE(Seg2_Original_Arrival_Date__c, "/", "-") & " " & LEFT(Seg2_Original_Arrival_Time__c, 5) & ":00")
          ) * 24 * 60, 0
        )
      ), 60)) & "分鐘", ""
    )
  )
)
